"""PT 4.x grading values normalized to those regenerated by the current Wizard."""
from lxml import etree
from conftest import make_pka_xml
from ptkit import PTFile
from ptkit.iosconfig import IosConfig
from ptkit.compatibility import repair_legacy_assessment
from ptkit.solver import _networks, prepare_solution


def fixture():
    pt = PTFile.from_xml(make_pka_xml(pt4=True, password='internal'))
    _, answer = _networks(pt)
    router = answer.find('NETWORK/DEVICES/DEVICE/ENGINE')
    running = router.find('RUNNINGCONFIG')
    cfg = IosConfig([line.text or '' for line in running])
    cfg.merge('interface FastEthernet0/0.99\n encapsulation dot1Q 99 native\n'
              'interface Serial0/0/0\n encapsulation ppp\nrouter ospf 1\n'
              ' passive-interface FastEthernet0/0.99')
    running.clear()
    for line in cfg.lines:
        etree.SubElement(running, 'LINE').text = line
    # A serial link in the opposite orientation exercises endpoint resolution.
    links = answer.find('NETWORK/LINKS')
    serial = etree.SubElement(links, 'LINK')
    etree.SubElement(serial, 'TYPE').text = 'eSerial'
    cable = etree.SubElement(serial, 'CABLE')
    for tag, value in [('FROM', '1'), ('PORT', 'Serial0/0/0'), ('TO', '0'), ('PORT', 'Serial0/0/0')]:
        etree.SubElement(cable, tag).text = value
    comparisons = pt.root.find('COMPARISONS')
    comparisons.clear()
    root = etree.SubElement(comparisons, 'NODE')
    etree.SubElement(root, 'NAME').text = 'Network'
    etree.SubElement(root, 'ID').text = 'Network'
    dev = etree.SubElement(root, 'NODE')
    etree.SubElement(dev, 'NAME').text = 'Router0'
    etree.SubElement(dev, 'ID').text = 'Router0'
    return pt, dev


def add(parent, path, expected='', variable=''):
    for name, ident in path:
        node = etree.SubElement(parent, 'NODE')
        etree.SubElement(node, 'NAME', checkType='1').text = name
        etree.SubElement(node, 'ID').text = ident
        parent = node
    label = parent.find('NAME')
    label.set('checkType', '2')
    label.set('nodeValue', expected)
    label.set('variableEnabled', 'false')
    label.set('variableName', variable)
    etree.SubElement(parent, 'POINTS').text = '3'
    return label


def test_legacy_link_ppp_native_and_passive_targets_are_repaired():
    pt, dev = fixture()
    copper = add(dev, [('Ports', 'Ports'), ('FastEthernet0/0', 'FastEthernet0/0'),
                       ('Link to PC0', 'Link to PC0'), ('Type', 'Type')])
    serial = add(dev, [('Ports', 'Ports'), ('Serial0/0/0', 'Serial0/0/0'),
                       ('Link to PC0', 'Link to PC0'), ('Type', 'Type')])
    remote = add(dev, [('Ports', 'Ports'), ('FastEthernet0/0', 'FastEthernet0/0'),
                       ('Link to PC0', 'Link to PC0'), ('Connects to FastEthernet0', 'Connects to FastEthernet0')])
    ppp = add(dev, [('Ports', 'Ports'), ('Serial0/0/0', 'Serial0/0/0'), ('Encapsulation', 'Encapsulation')])
    native = add(dev, [('Ports', 'Ports'), ('FastEthernet0/0.99', 'FastEthernet0/0.99'),
                       ('802.1Q', '802.1Q'), ('Native VLAN', 'Native VLAN')])
    passive = add(dev, [('OSPF', 'OSPF'), ('Process ID 1', '1'),
                        ('Passive Interface', 'Passive Interface'), ('FastEthernet0/0.99', 'FastEthernet0/0.99')],
                  'FastEthernet0/0.99')
    _, answer = _networks(pt)
    reference = pt.doc.fragment(answer)
    criteria = [(n.get('checkType'), n.getparent().findtext('ID'), n.getparent().findtext('POINTS'))
                for n in pt.root.iterfind('COMPARISONS//NAME')]
    repairs = repair_legacy_assessment(pt, answer)
    assert len(repairs) == 6
    assert [label.get('nodeValue') for label in (copper, serial, remote, ppp, native, passive)] == [
        '0 0', '2', 'Connects to FastEthernet0', 'PppProcess', '99', '1']
    assert pt.doc.fragment(answer) == reference
    assert criteria == [(n.get('checkType'), n.getparent().findtext('ID'), n.getparent().findtext('POINTS'))
                        for n in pt.root.iterfind('COMPARISONS//NAME')]
    assert repair_legacy_assessment(pt, answer) == []  # idempotent


def test_explicit_values_and_named_variables_are_preserved():
    pt, dev = fixture()
    path = [('Ports', 'Ports'), ('Serial0/0/0', 'Serial0/0/0'), ('Encapsulation', 'Encapsulation')]
    explicit = add(dev, path, 'ExplicitAuthorValue')
    variable = add(dev, path, '', 'CustomEncapsulation')
    _, answer = _networks(pt)
    assert repair_legacy_assessment(pt, answer) == []
    assert explicit.get('nodeValue') == 'ExplicitAuthorValue'
    assert variable.get('variableName') == 'CustomEncapsulation'


def test_no_reference_or_ambiguous_links_are_not_guessed():
    pt, dev = fixture()
    add(dev, [('Ports', 'Ports'), ('FastEthernet0/0', 'FastEthernet0/0'),
              ('Link to PC0', 'Link to PC0'), ('Type', 'Type')])
    _, answer = _networks(pt)
    from copy import deepcopy
    links = answer.find('NETWORK/LINKS')
    links.append(deepcopy(links[0]))
    assert repair_legacy_assessment(pt, answer) == []
    assert repair_legacy_assessment(pt, None) == []


def test_solution_reports_compatibility_repairs_and_keeps_source():
    pt, dev = fixture()
    add(dev, [('Ports', 'Ports'), ('Serial0/0/0', 'Serial0/0/0'), ('Encapsulation', 'Encapsulation')])
    before = pt.to_xml()
    xml, report = prepare_solution(pt)
    assert pt.to_xml() == before
    assert len(report['assessment_compatibility_repairs']) == 1
    assert b'nodeValue="PppProcess"' in xml
    assert report['packet_tracer_score'] is None
